-- Dados de exemplo. URLs já cadastradas não são inseridas novamente.
INSERT INTO links (url, titulo, descricao)
SELECT dados.url, dados.titulo, dados.descricao
FROM (VALUES
    ('https://www.python.org/', 'Python', 'Linguagem de programação Python e recursos oficiais.'),
    ('https://docs.python.org/3/', 'Documentação Python', 'Referência da linguagem Python e da biblioteca padrão.'),
    ('https://pandas.pydata.org/docs/', 'Documentação pandas', 'Análise e manipulação de dados em Python com tabelas.'),
    ('https://numpy.org/doc/', 'Documentação NumPy', 'Computação numérica, vetores e matrizes em Python.'),
    ('https://matplotlib.org/stable/', 'Documentação Matplotlib', 'Gráficos e visualizações de dados em Python.'),
    ('https://scikit-learn.org/stable/', 'Scikit-learn', 'Aprendizado de máquina para classificação, regressão e agrupamento.'),
    ('https://pytorch.org/docs/stable/', 'Documentação PyTorch', 'Biblioteca para aprendizado profundo e redes neurais.'),
    ('https://www.tensorflow.org/', 'TensorFlow', 'Plataforma para criar e treinar modelos de aprendizado de máquina.'),
    ('https://huggingface.co/docs', 'Documentação Hugging Face', 'Modelos de inteligência artificial, processamento de linguagem e datasets.'),
    ('https://www.sbert.net/', 'Sentence Transformers', 'Embeddings de texto e busca semântica com modelos de linguagem.'),
    ('https://jupyter.org/', 'Projeto Jupyter', 'Notebooks interativos para programação, ciência de dados e pesquisa.'),
    ('https://www.r-project.org/', 'Projeto R', 'Linguagem e ambiente para estatística e análise de dados.'),
    ('https://posit.co/', 'Posit', 'Ferramentas para ciência de dados com R e Python.'),
    ('https://www.postgresql.org/docs/', 'Documentação PostgreSQL', 'Referência do banco de dados PostgreSQL e da linguagem SQL.'),
    ('https://www.mysql.com/', 'MySQL', 'Banco de dados relacional e ferramentas associadas.'),
    ('https://www.sqlite.org/docs.html', 'Documentação SQLite', 'Banco de dados relacional incorporado e documentação SQL.'),
    ('https://redis.io/docs/', 'Documentação Redis', 'Armazenamento em memória, cache e estruturas de dados.'),
    ('https://www.mongodb.com/docs/', 'Documentação MongoDB', 'Banco de dados de documentos e consultas.'),
    ('https://fastapi.tiangolo.com/', 'FastAPI', 'Framework Python para criar APIs web com validação automática.'),
    ('https://www.djangoproject.com/', 'Django', 'Framework Python para desenvolvimento de aplicações web.'),
    ('https://flask.palletsprojects.com/', 'Flask', 'Framework Python para aplicações e APIs web.'),
    ('https://developer.mozilla.org/pt-BR/', 'MDN Web Docs', 'Documentação para desenvolvimento web, HTML, CSS e JavaScript.'),
    ('https://developer.mozilla.org/pt-BR/docs/Web/HTML', 'Guia HTML', 'Referência de HTML para estruturar páginas web.'),
    ('https://developer.mozilla.org/pt-BR/docs/Web/CSS', 'Guia CSS', 'Referência de CSS para estilos e layouts web.'),
    ('https://developer.mozilla.org/pt-BR/docs/Web/JavaScript', 'Guia JavaScript', 'Documentação da linguagem JavaScript para a web.'),
    ('https://www.typescriptlang.org/docs/', 'Documentação TypeScript', 'JavaScript com tipagem estática e ferramentas de desenvolvimento.'),
    ('https://react.dev/', 'React', 'Biblioteca para construir interfaces de usuário com componentes.'),
    ('https://vuejs.org/', 'Vue.js', 'Framework JavaScript para criar interfaces web.'),
    ('https://angular.dev/', 'Angular', 'Framework para desenvolver aplicações web com TypeScript.'),
    ('https://nodejs.org/', 'Node.js', 'Ambiente de execução JavaScript para servidores e ferramentas.'),
    ('https://git-scm.com/doc', 'Documentação Git', 'Controle de versão, commits, branches e trabalho em equipe.'),
    ('https://docs.github.com/', 'Documentação GitHub', 'Repositórios, colaboração, issues e automação de desenvolvimento.'),
    ('https://docs.docker.com/', 'Documentação Docker', 'Contêineres, imagens e execução de aplicações.'),
    ('https://kubernetes.io/docs/', 'Documentação Kubernetes', 'Orquestração e implantação de aplicações em contêineres.'),
    ('https://docs.aws.amazon.com/', 'Documentação AWS', 'Serviços de computação em nuvem da Amazon Web Services.'),
    ('https://cloud.google.com/docs', 'Documentação Google Cloud', 'Serviços de infraestrutura e computação em nuvem.'),
    ('https://learn.microsoft.com/azure/', 'Documentação Azure', 'Serviços de computação em nuvem da Microsoft.'),
    ('https://www.linux.org/', 'Linux', 'Recursos e informações sobre o sistema operacional Linux.'),
    ('https://www.gnu.org/', 'Projeto GNU', 'Software livre e ferramentas do sistema GNU.'),
    ('https://owasp.org/', 'OWASP', 'Segurança de aplicações web e recursos para desenvolvedores.'),
    ('https://cheatsheetseries.owasp.org/', 'OWASP Cheat Sheets', 'Guias práticos de segurança para aplicações e APIs.'),
    ('https://www.w3.org/', 'W3C', 'Padrões abertos para tecnologias da web e acessibilidade.'),
    ('https://www.w3.org/WAI/', 'Iniciativa de Acessibilidade Web', 'Diretrizes e recursos para criar conteúdos acessíveis.'),
    ('https://www.wikipedia.org/', 'Wikipédia', 'Enciclopédia livre com artigos em diversos idiomas.'),
    ('https://scholar.google.com/', 'Google Acadêmico', 'Pesquisa de artigos, livros e outras publicações acadêmicas.'),
    ('https://arxiv.org/', 'arXiv', 'Repositório aberto de pesquisas em ciência, matemática e computação.'),
    ('https://pubmed.ncbi.nlm.nih.gov/', 'PubMed', 'Pesquisa de literatura biomédica e artigos científicos.'),
    ('https://openalex.org/', 'OpenAlex', 'Catálogo aberto de publicações, autores e instituições científicas.'),
    ('https://www.crossref.org/', 'Crossref', 'Metadados acadêmicos e identificadores de publicações científicas.'),
    ('https://www.kaggle.com/', 'Kaggle', 'Conjuntos de dados, notebooks e desafios de ciência de dados.')
) AS dados(url, titulo, descricao)
WHERE NOT EXISTS (SELECT 1 FROM links WHERE links.url = dados.url);
